src/habitRepo.ts<pre><code>import type { SQLiteDatabase } from 'expo-sqlite';

export type HabitRow = { id: string; name: string; created_at: string; archived: number; done_today: number };

export function listHabits(db: SQLiteDatabase, today: string) {
  return db.getAllAsync&lt;HabitRow&gt;(
    `SELECT h.*, EXISTS(SELECT 1 FROM checkins c WHERE c.habit_id = h.id AND c.day = ?) AS done_today
       FROM habits h
      WHERE h.archived = 0
      ORDER BY h.created_at`,
    today,
  );
}

export async function toggleCheckin(db: SQLiteDatabase, habitId: string, day: string) {
  const res = await db.runAsync('DELETE FROM checkins WHERE habit_id = ? AND day = ?', habitId, day);
  if (res.changes === 0) {
    await db.runAsync('INSERT INTO checkins (habit_id, day) VALUES (?, ?)', habitId, day);
  }
}

export function addHabit(db: SQLiteDatabase, id: string, name: string, createdAt: string) {
  return db.runAsync('INSERT INTO habits (id, name, created_at) VALUES (?, ?, ?)', id, name, createdAt);
}
</code></pre> <p>Always pass values as parameters (<code>?</code>), never by string concatenation — that's how SQL injection happens, even in a local database (a habit named <code>'); DROP TABLE habits; --</code> should be stored, not executed).</p>

app/index.tsx<pre><code>import { useCallback, useState } from 'react';
import { FlatList, Pressable, Text } from 'react-native';
import { useFocusEffect } from 'expo-router';
import { useSQLiteContext } from 'expo-sqlite';
import { HabitRow, listHabits, toggleCheckin } from '../src/habitRepo';

const todayKey = () =&gt; new Date().toISOString().slice(0, 10); // demo only: UTC day; use local day keys (L1-10) in real code

export default function Today() {
  const db = useSQLiteContext();
  const [habits, setHabits] = useState&lt;HabitRow[]&gt;([]);

  const reload = useCallback(async () =&gt; setHabits(await listHabits(db, todayKey())), [db]);

  useFocusEffect(useCallback(() =&gt; { reload(); }, [reload]));

  async function toggle(id: string) {
    await toggleCheckin(db, id, todayKey());
    await reload();
  }

  return (
    &lt;FlatList
      data={habits}
      keyExtractor={(h) =&gt; h.id}
      renderItem={({ item }) =&gt; (
        &lt;Pressable onPress={() =&gt; toggle(item.id)} style={{ padding: 16 }}&gt;
          &lt;Text&gt;{item.done_today ? '✅' : '⬜️'} {item.name}&lt;/Text&gt;
        &lt;/Pressable&gt;
      )}
    /&gt;
  );
}
</code></pre> <p>Kill the app, reopen it, and the check-ins are still there.</p>

src/habitSchema.ts<pre><code>import { z } from 'zod';

export const habitSchema = z
  .object({
    name: z.string().trim().min(2, 'Use at least 2 characters.').max(40, 'Keep it under 40 characters.'),
    frequency: z.enum(['daily', 'weekly']),
    timesPerWeek: z.coerce.number().int('Whole numbers only.').min(1).max(7),
    reminder: z.boolean(),
    reminderTime: z
      .string()
      .regex(/^([01]\d|2[0-3]):[0-5]\d$/, 'Use 24-hour HH:MM.')
      .optional()
      .or(z.literal('')),
    startDate: z.string().regex(/^\d{4}-\d{2}-\d{2}$/, 'Use YYYY-MM-DD.'),
    endDate: z.string().regex(/^\d{4}-\d{2}-\d{2}$/, 'Use YYYY-MM-DD.').optional().or(z.literal('')),
  })
  .refine((v) =&gt; !v.reminder || !!v.reminderTime, {
    path: ['reminderTime'],
    message: 'Pick a reminder time, or turn reminders off.',
  })
  .refine((v) =&gt; !v.endDate || v.endDate &gt;= v.startDate, {
    path: ['endDate'],
    message: 'End date must be on or after the start date.',
  });

export type HabitFormInput = z.input&lt;typeof habitSchema&gt;;   // what the fields hold (strings from TextInput)
export type HabitFormValues = z.output&lt;typeof habitSchema&gt;; // what you get after parsing (numbers, trimmed)
</code></pre> <p>Things to notice:</p> <ul> <li><code>z.coerce.number()</code> turns the string a <code>TextInput</code> produces into a number, then validates it.</li> <li><code>.trim()</code> normalises before checking length, so <code>"  a "</code> fails.</li> <li><code>.refine</code> adds cross-field rules; <code>path</code> attaches the error to the field the user should fix.</li> <li>Comparing <code>YYYY-MM-DD</code> strings with <code>&gt;=</code> works because that format sorts lexicographically in date   order.</li> <li><code>z.input</code> and <code>z.output</code> give you two types for free: the raw form values and the parsed result.</li> </ul> <p>Because the schema is plain TypeScript, you can test it without React. These tests were run with Jest (zod 4.6, react-hook-form 7.89) and passed:</p> src/habitSchema.test.ts<pre><code>import { habitSchema } from './habitSchema';

const base = {
  name: 'Read', frequency: 'weekly', timesPerWeek: '3', reminder: false,
  reminderTime: '', startDate: '2026-10-01', endDate: '',
};

test('valid input parses and coerces', () =&gt; {
  const r = habitSchema.safeParse(base);
  expect(r.success).toBe(true);
  if (r.success) expect(r.data.timesPerWeek).toBe(3);
});

test('reminder on without a time is rejected on the right field', () =&gt; {
  const r = habitSchema.safeParse({ ...base, reminder: true });
  expect(r.success).toBe(false);
  if (!r.success) expect(r.error.issues[0].path).toEqual(['reminderTime']);
});

test('end date before start date is rejected', () =&gt; {
  const r = habitSchema.safeParse({ ...base, endDate: '2026-09-30' });
  expect(r.success).toBe(false);
  if (!r.success) expect(r.error.issues.map((i) =&gt; i.path[0])).toContain('endDate');
});

test('name is trimmed before length check', () =&gt; {
  expect(habitSchema.safeParse({ ...base, name: '  a ' }).success).toBe(false);
});
</code></pre>

app/add.tsx<pre><code>import { useForm, Controller } from 'react-hook-form';
