src/ReminderSetting.tsx<pre><code>import { useEffect, useState } from 'react';
import { Switch, Text, View } from 'react-native';
import AsyncStorage from '@react-native-async-storage/async-storage';
import * as Notifications from 'expo-notifications';
import { ensureNotificationPermission } from './notifications';

const KEY = 'reminder:id';

export function ReminderSetting({ hour = 20, minute = 0 }: { hour?: number; minute?: number }) {
  const [enabled, setEnabled] = useState(false);
  const [note, setNote] = useState&lt;string | null&gt;(null);

  useEffect(() =&gt; {
    AsyncStorage.getItem(KEY).then((id) =&gt; setEnabled(!!id));
  }, []);

  async function toggle(next: boolean) {
    setNote(null);
    const existing = await AsyncStorage.getItem(KEY);
    if (existing) await Notifications.cancelScheduledNotificationAsync(existing);
    if (!next) {
      await AsyncStorage.removeItem(KEY);
      setEnabled(false);
      return;
    }
    if (!(await ensureNotificationPermission())) {
      setNote('Notifications are off for this app. You can turn them on in Settings.');
      setEnabled(false);
      return;
    }
    const id = await Notifications.scheduleNotificationAsync({
      content: { title: 'Habit check-in', body: 'Log today’s habits before bed.', data: { url: '/' } },
      trigger: { type: Notifications.SchedulableTriggerInputTypes.DAILY, hour, minute, channelId: 'reminders' },
    });
    await AsyncStorage.setItem(KEY, id);
    setEnabled(true);
  }

  return (
    &lt;View style={{ padding: 16, gap: 6 }}&gt;
      &lt;View style={{ flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between' }}&gt;
        &lt;Text style={{ fontSize: 16 }}&gt;Daily reminder at {String(hour).padStart(2, '0')}:{String(minute).padStart(2, '0')}&lt;/Text&gt;
        &lt;Switch value={enabled} onValueChange={toggle} accessibilityLabel="Daily reminder" /&gt;
      &lt;/View&gt;
      {note &amp;&amp; &lt;Text style={{ color: '#b45309' }}&gt;{note}&lt;/Text&gt;}
    &lt;/View&gt;
  );
}
</code></pre> <p>Cancelling the stored identifier before scheduling a new one is what prevents duplicate reminders when the toggle is flipped repeatedly.</p>

src/ProgressBar.tsx<pre><code>import { useEffect } from 'react';
import { StyleSheet, View } from 'react-native';
import Animated, { useAnimatedStyle, useSharedValue, withSpring } from 'react-native-reanimated';

export function ProgressBar({ progress }: { progress: number }) {  // 0..1
  const p = useSharedValue(0);

  useEffect(() =&gt; {
    p.value = withSpring(Math.min(Math.max(progress, 0), 1), { damping: 18, stiffness: 140 });
  }, [progress, p]);

  const fill = useAnimatedStyle(() =&gt; ({
    transform: [{ scaleX: p.value }],
  }));

  return (
    &lt;View style={styles.track} accessibilityRole="progressbar" accessibilityValue={{ min: 0, max: 100, now: Math.round(progress * 100) }}&gt;
      &lt;Animated.View style={[styles.fill, fill]} /&gt;
    &lt;/View&gt;
  );
}

const styles = StyleSheet.create({
  track: { height: 10, borderRadius: 5, backgroundColor: '#e2e8f0', overflow: 'hidden' },
  fill: { ...StyleSheet.absoluteFill, backgroundColor: '#22c55e', transformOrigin: 'left' },
});
</code></pre> <p>Setting <code>p.value = withSpring(…)</code> starts a spring on the UI thread. Every frame, the <code>useAnimatedStyle</code> worklet re-runs there and updates the native view directly — React doesn't re-render at all. Animating <code>scaleX</code> with <code>transformOrigin: 'left'</code> instead of <code>width</code> keeps it to a transform, which is cheaper than relayout (Reanimated can animate <code>width</code>, but transforms avoid running Yoga every frame).</p>

src/CompleteButton.tsx<pre><code>import { Pressable, StyleSheet, Text } from 'react-native';
import Animated, {
  useAnimatedStyle, useSharedValue, withSequence, withSpring, withTiming, interpolateColor, useReducedMotion,
} from 'react-native-reanimated';
import { scheduleOnRN } from 'react-native-worklets';
import * as Haptics from 'expo-haptics';

export function CompleteButton({ done, onToggle }: { done: boolean; onToggle: () =&gt; void }) {
  const scale = useSharedValue(1);
  const progress = useSharedValue(done ? 1 : 0);
  const reduce = useReducedMotion();

  function press() {
    const next = !done;
    progress.value = withTiming(next ? 1 : 0, { duration: 220 });
    if (next &amp;&amp; !reduce) {
      scale.value = withSequence(
        withTiming(0.85, { duration: 90 }),
        withSpring(1.12, { damping: 6, stiffness: 300 }),
        withSpring(1, { damping: 12 }, (finished) =&gt; {
          // This callback runs on the UI thread; hop back to JS for non-worklet APIs.
          if (finished) scheduleOnRN(Haptics.notificationAsync, Haptics.NotificationFeedbackType.Success);
        }),
      );
    }
    onToggle();
  }

  const circle = useAnimatedStyle(() =&gt; ({
    transform: [{ scale: scale.value }],
    backgroundColor: interpolateColor(progress.value, [0, 1], ['#ffffff', '#22c55e']),
    borderColor: interpolateColor(progress.value, [0, 1], ['#cbd5e1', '#22c55e']),
  }));
  const tick = useAnimatedStyle(() =&gt; ({ opacity: progress.value, transform: [{ scale: 0.6 + progress.value * 0.4 }] }));

  return (
    &lt;Pressable onPress={press} hitSlop={8} accessibilityRole="checkbox" accessibilityState={{ checked: done }}&gt;
      &lt;Animated.View style={[styles.circle, circle]}&gt;
        &lt;Animated.Text style={[styles.tick, tick]}&gt;✓&lt;/Animated.Text&gt;
      &lt;/Animated.View&gt;
    &lt;/Pressable&gt;
  );
}

const styles = StyleSheet.create({
  circle: { width: 36, height: 36, borderRadius: 18, borderWidth: 2, alignItems: 'center', justifyContent: 'center' },
  tick: { color: 'white', fontSize: 18, fontWeight: '800' },
});
</code></pre> <p><code>scheduleOnRN</code> (from <code>react-native-worklets</code>) schedules a call on the JS thread from a worklet. Older Reanimated code uses <code>runOnJS(fn)(args)</code> for the same purpose; in the Reanimated 4 / worklets versions checked for this lesson, <code>scheduleOnRN</code> is the API exported for it.</p>

src/SwipeToComplete.tsx<pre><code>import { ReactNode } from 'react';
import { StyleSheet, Text, View, useWindowDimensions } from 'react-native';
import { Gesture, GestureDetector } from 'react-native-gesture-handler';
import Animated, { interpolate, Extrapolation, useAnimatedStyle, useSharedValue, withSpring, withTiming } from 'react-native-reanimated';
import { scheduleOnRN } from 'react-native-worklets';
import * as Haptics from 'expo-haptics';

type Props = { children: ReactNode; onComplete: () =&gt; void; label?: string };

export function SwipeToComplete({ children, onComplete, label = 'Done' }: Props) {
  const { width } = useWindowDimensions();
  const threshold = width * 0.35;
  const x = useSharedValue(0);
  const passed = useSharedValue(false);

  const pan = Gesture.Pan()
    .activeOffsetX(12)          // only rightward swipes activate
    .failOffsetY([-8, 8])
    .onChange((e) =&gt; {
      x.value = Math.max(0, x.value + e.changeX);
      const nowPassed = x.value &gt; threshold;
      if (nowPassed !== passed.value) {
        passed.value = nowPassed;
        scheduleOnRN(Haptics.selectionAsync);   // tick when crossing the threshold
      }
    })
    .onEnd(() =&gt; {
      if (x.value &gt; threshold) {
        x.value = withTiming(width, { duration: 180 }, (finished) =&gt; {
          if (finished) {
            scheduleOnRN(onComplete);
            x.value = 0;          // reset for reuse (the parent usually re-renders the row as done)
            passed.value = false;
          }
        });
      } else {
        x.value = withSpring(0, { damping: 18 });
        passed.value = false;
      }
    });

  const rowStyle = useAnimatedStyle(() =&gt; ({ transform: [{ translateX: x.value }] }));
  const bgStyle = useAnimatedStyle(() =&gt; ({
    opacity: interpolate(x.value, [0, threshold], [0.3, 1], Extrapolation.CLAMP),
  }));

  return (
    &lt;View style={styles.container} accessibilityActions={[{ name: 'activate', label }]} onAccessibilityAction={onComplete}&gt;
      &lt;Animated.View style={[styles.background, bgStyle]}&gt;
        &lt;Text style={styles.backgroundText}&gt;✓ {label}&lt;/Text&gt;
      &lt;/Animated.View&gt;
      &lt;GestureDetector gesture={pan}&gt;
        &lt;Animated.View style={rowStyle}&gt;{children}&lt;/Animated.View&gt;
      &lt;/GestureDetector&gt;
    &lt;/View&gt;
  );
}

const styles = StyleSheet.create({
  container: { borderRadius: 14, overflow: 'hidden' },
  background: { ...StyleSheet.absoluteFill, backgroundColor: '#16a34a', justifyContent: 'center', paddingLeft: 20 },
  backgroundText: { color: 'white', fontWeight: '800', fontSize: 16 },
});
</code></pre> <p>Two details make it production-quality. The haptic tick fires once when crossing the threshold in either direction (tracked in a shared value so it lives on the UI thread). And the <code>accessibilityActions</code> give screen-reader users an equivalent — a swipe gesture alone is invisible to VoiceOver and TalkBack users (lesson 7). Use it inside a <code>FlatList</code> row: vertical scrolling still works because of <code>failOffsetY</code>.</p>

src/Stepper.tsx<pre><code>import { Pressable, StyleSheet, Text, View } from 'react-native';

type Props = { label: string; value: number; min: number; max: number; onChange: (v: number) =&gt; void };

export function Stepper({ label, value, min, max, onChange }: Props) {
  const dec = () =&gt; value &gt; min &amp;&amp; onChange(value - 1);
  const inc = () =&gt; value &lt; max &amp;&amp; onChange(value + 1);

  return (
    &lt;View
      accessible
      accessibilityRole="adjustable"
      accessibilityLabel={label}
      accessibilityValue={{ min, max, now: value, text: `${value} per week` }}
      accessibilityActions={[{ name: 'increment' }, { name: 'decrement' }]}
      onAccessibilityAction={(e) =&gt; (e.nativeEvent.actionName === 'increment' ? inc() : dec())}
      style={styles.row}
    &gt;
      &lt;Text style={styles.label}&gt;{label}&lt;/Text&gt;
      &lt;View style={styles.controls}&gt;
        &lt;Pressable onPress={dec} disabled={value &lt;= min} hitSlop={8} style={styles.button} importantForAccessibility="no"&gt;
          &lt;Text style={styles.buttonText}&gt;−&lt;/Text&gt;
        &lt;/Pressable&gt;
        &lt;Text style={styles.value}&gt;{value}&lt;/Text&gt;
        &lt;Pressable onPress={inc} disabled={value &gt;= max} hitSlop={8} style={styles.button} importantForAccessibility="no"&gt;
          &lt;Text style={styles.buttonText}&gt;+&lt;/Text&gt;
        &lt;/Pressable&gt;
      &lt;/View&gt;
    &lt;/View&gt;
  );
}

const styles = StyleSheet.create({
  row: { flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', paddingVertical: 8, minHeight: 48 },
  label: { fontSize: 16, flexShrink: 1 },
  controls: { flexDirection: 'row', alignItems: 'center', gap: 12 },
  button: { width: 44, height: 44, borderRadius: 22, backgroundColor: '#eef2ff', alignItems: 'center', justifyContent: 'center' },
  buttonText: { fontSize: 22, color: '#3730a3', fontWeight: '700' },
  value: { minWidth: 24, textAlign: 'center', fontSize: 18, fontVariant: ['tabular-nums'] },
});
</code></pre> <p>To a sighted user it's two buttons and a number. To a screen-reader user it's one adjustable element — "Times per week, 3 per week, adjustable" — that they change by swiping up or down, which is exactly how native steppers behave.</p>

modules/device-health/ios/DeviceHealthModule.swift<pre><code>import ExpoModulesCore
import UIKit

public class DeviceHealthModule: Module {
  public func definition() -&gt; ModuleDefinition {
    Name("DeviceHealth")

    Events("onPowerSaveChange")

    // Synchronous and cheap: reading a file-system attribute.
    Function("getFreeDiskBytes") { () -&gt; Double in
      let url = URL(fileURLWithPath: NSHomeDirectory())
      let values = try url.resourceValues(forKeys: [.volumeAvailableCapacityForImportantUsageKey])
      return Double(values.volumeAvailableCapacityForImportantUsage ?? 0)
    }

    // Battery level in 0...1, or -1 when unknown (e.g. the Simulator).
    AsyncFunction("getBatteryLevelAsync") { () -&gt; Double in
      return await MainActor.run {
        UIDevice.current.isBatteryMonitoringEnabled = true
        return Double(UIDevice.current.batteryLevel)
      }
    }

    Function("isPowerSaveEnabled") { () -&gt; Bool in
      ProcessInfo.processInfo.isLowPowerModeEnabled
    }

    OnStartObserving {
      NotificationCenter.default.addObserver(
        self,
        selector: #selector(self.powerStateChanged),
        name: Notification.Name.NSProcessInfoPowerStateDidChange,
        object: nil
      )
    }

    OnStopObserving {
      NotificationCenter.default.removeObserver(self, name: Notification.Name.NSProcessInfoPowerStateDidChange, object: nil)
    }
  }

  @objc
  private func powerStateChanged() {
    sendEvent("onPowerSaveChange", ["enabled": ProcessInfo.processInfo.isLowPowerModeEnabled])
  }
}
</code></pre> <p><code>UIDevice</code> APIs must be used on the main thread, hence <code>MainActor.run</code>. <code>throws</code> from <code>resourceValues</code> propagate to JavaScript as a rejected call/exception automatically.</p>

modules/device-health/android/src/main/java/expo/modules/devicehealth/DeviceHealthModule.kt<pre><code>package expo.modules.devicehealth

import android.content.BroadcastReceiver
import android.content.Context
import android.content.Intent
import android.content.IntentFilter
import android.os.BatteryManager
import android.os.PowerManager
import android.os.StatFs
import expo.modules.kotlin.exception.Exceptions
import expo.modules.kotlin.modules.Module
import expo.modules.kotlin.modules.ModuleDefinition

class DeviceHealthModule : Module() {
  private val context: Context
    get() = appContext.reactContext ?: throw Exceptions.ReactContextLost()

  private var receiver: BroadcastReceiver? = null

  override fun definition() = ModuleDefinition {
    Name("DeviceHealth")

    Events("onPowerSaveChange")

    Function("getFreeDiskBytes") {
      StatFs(context.filesDir.path).availableBytes.toDouble()
    }

    AsyncFunction("getBatteryLevelAsync") {
      val bm = context.getSystemService(Context.BATTERY_SERVICE) as BatteryManager
      val percent = bm.getIntProperty(BatteryManager.BATTERY_PROPERTY_CAPACITY)
      if (percent in 0..100) percent / 100.0 else -1.0
    }

    Function("isPowerSaveEnabled") {
      (context.getSystemService(Context.POWER_SERVICE) as PowerManager).isPowerSaveMode
    }

    OnStartObserving {
      val r = object : BroadcastReceiver() {
        override fun onReceive(c: Context, intent: Intent) {
          val pm = c.getSystemService(Context.POWER_SERVICE) as PowerManager
          sendEvent("onPowerSaveChange", mapOf("enabled" to pm.isPowerSaveMode))
        }
      }
      context.registerReceiver(r, IntentFilter(PowerManager.ACTION_POWER_SAVE_MODE_CHANGED))
      receiver = r
    }

    OnStopObserving {
      receiver?.let { context.unregisterReceiver(it) }
      receiver = null
    }
  }
}
</code></pre> <p>The function names, argument types and return types match the Swift side exactly — that shared contract is what the TypeScript declaration describes.</p>

