  }

  return (
    &lt;KeyboardAvoidingView style={{ flex: 1 }} behavior={Platform.OS === 'ios' ? 'padding' : undefined}&gt;
      &lt;ScrollView contentContainerStyle={{ padding: 16, gap: 12 }} keyboardShouldPersistTaps="handled"&gt;
        &lt;TextInput value={body} onChangeText={setBody} placeholder="What did you observe?" multiline
          style={{ minHeight: 120, fontSize: 16, textAlignVertical: 'top', backgroundColor: 'white', borderRadius: 10, padding: 12 }} /&gt;
        {photo &amp;&amp; &lt;Image source={{ uri: photo }} style={{ width: '100%', aspectRatio: 4 / 3, borderRadius: 12 }} /&gt;}
        &lt;Button title={photo ? 'Retake photo' : 'Add photo'} onPress={() =&gt; setCameraOpen(true)} /&gt;
        &lt;Button title={locating ? 'Locating…' : tag ? 'Update location' : 'Add location'} onPress={addLocation} disabled={locating} /&gt;
        {tag &amp;&amp; &lt;Text&gt;{tag.label ?? `${tag.latitude.toFixed(4)}, ${tag.longitude.toFixed(4)}`}{tag.stale ? ' (approximate)' : ''}&lt;/Text&gt;}
        {tag === null &amp;&amp; !locating &amp;&amp; &lt;Text style={{ color: '#64748b' }}&gt;Location is optional.&lt;/Text&gt;}
        &lt;Button title="Save note" onPress={save} disabled={!body.trim()} /&gt;
      &lt;/ScrollView&gt;
      &lt;Modal visible={cameraOpen} animationType="slide" onRequestClose={() =&gt; setCameraOpen(false)}&gt;
        &lt;CaptureScreen onCaptured={(uri) =&gt; { setPhoto(uri); setCameraOpen(false); }} /&gt;
      &lt;/Modal&gt;
    &lt;/KeyboardAvoidingView&gt;
  );
}
</code></pre>

app/log.tsx<pre><code>import { memo, useCallback, useMemo } from 'react';
import { StyleSheet, Text, View } from 'react-native';
import { FlashList, ListRenderItem } from '@shopify/flash-list';

type Row =
  | { kind: 'day'; id: string; label: string }
  | { kind: 'checkin'; id: string; habit: string; time: string };

const fmt = new Intl.DateTimeFormat(undefined, { weekday: 'short', month: 'short', day: 'numeric' });

function buildRows(count: number): Row[] {
  const rows: Row[] = [];
  const start = new Date(2026, 0, 1);
  for (let d = 0; d &lt; count / 5; d++) {
    const date = new Date(start.getFullYear(), start.getMonth(), start.getDate() + d);
    rows.push({ kind: 'day', id: `d${d}`, label: fmt.format(date) });   // format once, here
    for (let i = 0; i &lt; 4; i++) rows.push({ kind: 'checkin', id: `d${d}-${i}`, habit: `Habit ${i + 1}`, time: `${7 + i * 3}:00` });
  }
  return rows;
}

const DayHeader = memo(({ label }: { label: string }) =&gt; &lt;Text style={styles.day}&gt;{label}&lt;/Text&gt;);
const CheckinRow = memo(({ habit, time }: { habit: string; time: string }) =&gt; (
  &lt;View style={styles.row}&gt;&lt;Text style={styles.habit}&gt;{habit}&lt;/Text&gt;&lt;Text style={styles.time}&gt;{time}&lt;/Text&gt;&lt;/View&gt;
));

export default function Log() {
  const rows = useMemo(() =&gt; buildRows(5000), []);
  const renderItem = useCallback&lt;ListRenderItem&lt;Row&gt;&gt;(({ item }) =&gt;
    item.kind === 'day' ? &lt;DayHeader label={item.label} /&gt; : &lt;CheckinRow habit={item.habit} time={item.time} /&gt;, []);

  return (
    &lt;FlashList
      data={rows}
      keyExtractor={(r) =&gt; r.id}
      getItemType={(r) =&gt; r.kind}
      renderItem={renderItem}
    /&gt;
  );
}

const styles = StyleSheet.create({
  day: { paddingHorizontal: 16, paddingTop: 20, paddingBottom: 6, fontWeight: '700', color: '#475569', backgroundColor: '#f8fafc' },
  row: { flexDirection: 'row', justifyContent: 'space-between', paddingHorizontal: 16, paddingVertical: 12 },
  habit: { fontSize: 16 },
  time: { color: '#64748b', fontVariant: ['tabular-nums'] },
});
</code></pre> <p>To compare, swap <code>FlashList</code> for <code>FlatList</code> (removing <code>getItemType</code>), build both in release mode, and fling through the list on a mid-range Android phone with the perf monitor open. Record what you observe — blank areas, JS frame rate — rather than relying on anyone's published benchmark.</p>

src/HabitRow.test.tsx<pre><code>import { render, screen, userEvent } from '@testing-library/react-native';
import { HabitRow } from './HabitRow';

const colors = { bg: '#fff', surface: '#fff', text: '#000', muted: '#666', border: '#ccc', primary: '#00f', success: '#0a0' };

test('exposes checkbox role, name and checked state, and toggles by id', async () =&gt; {
  const user = userEvent.setup();
  const onToggle = jest.fn();
  await render(
    &lt;HabitRow id="h1" name="Drink water" streak={3} doneToday colors={colors} onToggle={onToggle} onDelete={jest.fn()} /&gt;,
  );

  const row = screen.getByRole('checkbox', { name: 'Drink water, 3 day streak' });
  expect(row).toBeChecked();
  expect(screen.getByText('3-day streak')).toBeOnTheScreen();

  await user.press(row);
  expect(onToggle).toHaveBeenCalledWith('h1');
});
</code></pre> <p>This test fails if someone removes <code>accessibilityRole</code>, changes the label, or forgets <code>accessibilityState</code> — regressions a visual check wouldn't catch.</p>

